package com.rqmbooks.rafiqalquran.logic;

import java.util.List;

/**
 * Structural mushaf metadata (juz, Madani page, hizb) for every verse.
 *
 * This is layout metadata only — which page of the standard Madani mushaf a verse
 * is printed on. The Arabic text and translations come exclusively from the
 * validated dataset; this table never supplies scripture.
 *
 * The table is generated by mobile/android/scripts/fetchQuranMeta.js from the
 * public Quran.com API v4 structural fields and bundled as assets/quran-meta.tsv.
 */
public final class QuranMeta {
    public static final int PAGES = 604;
    public static final int JUZ_COUNT = 30;
    public static final int HIZB_COUNT = 240;
    public static final int VERSE_COUNT = 6236;

    private final int[] page;
    private final int[] juz;
    private final int[] hizb;
    private final int count;

    private QuranMeta(int[] page, int[] juz, int[] hizb) {
        this.page = page;
        this.juz = juz;
        this.hizb = hizb;
        this.count = page.length - 1;
    }

    /** Parses the bundled TSV. Throws when the table is incomplete or malformed. */
    public static QuranMeta parse(List<String> lines) {
        int[] page = new int[VERSE_COUNT + 1];
        int[] juz = new int[VERSE_COUNT + 1];
        int[] hizb = new int[VERSE_COUNT + 1];
        int index = 0;
        int lastPage = 0;
        int lastJuz = 0;
        int lastHizb = 0;
        for (String line : lines) {
            if (line == null) continue;
            String trimmed = line.trim();
            if (trimmed.isEmpty() || trimmed.startsWith("#")) continue;
            String[] parts = trimmed.split("\t", -1);
            if (parts.length < 4) throw new IllegalStateException("Malformed quran-meta row: " + trimmed);
            if (!parts[0].matches("\\d+:\\d+")) throw new IllegalStateException("Bad verse key: " + parts[0]);
            index++;
            if (index > VERSE_COUNT) throw new IllegalStateException("quran-meta has more than " + VERSE_COUNT + " rows");
            int pageNumber = Integer.parseInt(parts[2]);
            int juzNumber = Integer.parseInt(parts[1]);
            int hizbNumber = Integer.parseInt(parts[3]);
            if (pageNumber < 1 || pageNumber > PAGES) throw new IllegalStateException("Bad page " + pageNumber);
            if (juzNumber < 1 || juzNumber > JUZ_COUNT) throw new IllegalStateException("Bad juz " + juzNumber);
            if (hizbNumber < 1 || hizbNumber > HIZB_COUNT) throw new IllegalStateException("Bad hizb " + hizbNumber);
            if (pageNumber < lastPage || juzNumber < lastJuz || hizbNumber < lastHizb) {
                throw new IllegalStateException("Metadata regressed at " + parts[0]);
            }
            page[index] = pageNumber;
            juz[index] = juzNumber;
            hizb[index] = hizbNumber;
            lastPage = pageNumber;
            lastJuz = juzNumber;
            lastHizb = hizbNumber;
        }
        if (index != VERSE_COUNT) throw new IllegalStateException("Expected " + VERSE_COUNT + " meta rows, found " + index);
        if (lastPage != PAGES) throw new IllegalStateException("Expected last page " + PAGES + ", found " + lastPage);
        if (lastJuz != JUZ_COUNT) throw new IllegalStateException("Expected last juz " + JUZ_COUNT + ", found " + lastJuz);
        return new QuranMeta(page, juz, hizb);
    }

    public int verseCount() { return count; }

    public int page(int verseId) { return bounded(page, verseId); }
    public int juz(int verseId) { return bounded(juz, verseId); }
    public int hizb(int verseId) { return bounded(hizb, verseId); }

    /** "Juz 3 · Page 42" — the indicator shown in the reader. */
    public String indicator(int verseId) {
        return "Juz " + juz(verseId) + "  \u00B7  Page " + page(verseId);
    }

    /** Chapter start metadata, using the first verse id of the chapter. */
    public String chapterIndicator(Dataset dataset, int chapterId) {
        List<Verse> verses = dataset.chapterVerses(chapterId);
        if (verses.isEmpty()) return "";
        Verse first = verses.get(0);
        Verse last = verses.get(verses.size() - 1);
        int firstPage = page(first.id);
        int lastPage = page(last.id);
        String pages = firstPage == lastPage ? "Page " + firstPage : "Pages " + firstPage + "\u2013" + lastPage;
        return "Juz " + juz(first.id) + (juz(last.id) == juz(first.id) ? "" : "\u2013" + juz(last.id)) + "  \u00B7  " + pages;
    }

    private static int bounded(int[] values, int verseId) {
        if (verseId < 1 || verseId >= values.length) return 0;
        return values[verseId];
    }
}
